#include <cstdio>
#include <algorithm>
#include <vector>
#include <stack>

using namespace std;

int input_value()
{
    int val;
    scanf("%d",&val);
    return val;
}

bool visited_nodes[1000007];
const int MODULUS=1000000007;
long long divisor_freq[1000007];
long long cycle_sizes[1000007];
long long dynamic_prog[1000007];

int main()
{
    long long total_result=1;
    int p_value, k_value;
    p_value=input_value();
    k_value=input_value();
    for(int i=0; i<p_value; i++)
    {
        if(!visited_nodes[i])
        {
            int size=0;
            long long current=i;
            while(!visited_nodes[current])
            {
                visited_nodes[current]=1;
                current=((long long)k_value*current)%p_value;
                size++;
            }
            cycle_sizes[size]++;
        }
    }
    for(int i=1; i<=p_value; i++)
    {
        dynamic_prog[i]=((long long)cycle_sizes[i]*i)%MODULUS;
    }
    for(int i=1; i<=p_value; i++)
    {
        divisor_freq[i]=(divisor_freq[i]+dynamic_prog[i])%MODULUS;
        for(int j=i+i; j<=p_value; j+=i)
        {
            divisor_freq[j]=(dynamic_prog[i]+divisor_freq[j])%MODULUS;
        }
    }
    for(int i=1; i<=p_value; i++)
    {
        if(i==1)
        {
            for(int j=0; j<cycle_sizes[i]-1; j++)
                total_result=(total_result*(long long)cycle_sizes[i])%MODULUS;
        }
        else
        {
            for(int j=0; j<cycle_sizes[i]; j++)
                total_result=(total_result*(long long)divisor_freq[i])%MODULUS;
        }
    }
    if(k_value==1) total_result=(total_result*divisor_freq[1])%MODULUS;
    printf("%lld", total_result);
    return 0;
}
